package com.voltledger.billing;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/** Immutable invoice preview generated by the Java billing service. */
public record ElectricityBill(
    String invoiceNumber,
    LocalDate generatedOn,
    Consumer consumer,
    String tariffName,
    BigDecimal consumedUnits,
    List<BillLine> lines,
    BigDecimal energyCharge,
    BigDecimal fixedCharge,
    BigDecimal subtotal,
    BigDecimal tax,
    BigDecimal total
) { }
